from pathlib import Path
import json,pandas as pd,numpy as np
r=Path(__file__).resolve().parents[1];a=pd.read_csv(r/'results/summary.csv');b=pd.read_csv(r/'results/pvt/summary.csv');a=a[np.isclose(a.alpha,.1)].set_index('method');b=b[np.isclose(b.alpha,.1)].set_index('method')
pct=lambda x:f'{x*100:.2f}'
body={
'objectives':'Polyp segmentation masks may undergo largest-connected-component (LCC) cleanup after recall calibration. We investigated whether this operation preserves the calibrated fraction of missed annotated polyp area and compared corrections that respect the final mask geometry.',
'methods':'We evaluated published PraNet and Polyp-PVT checkpoints on four public datasets. Exact decoded-image checks removed 37 repeated test images, retaining 701 images. Seven procedures were compared over 500 shared random splits, each containing 350 calibration and 351 evaluation images, at a 10% expected missed-area target. Comparators included raw calibration, subsequent LCC cleanup, final-mask recalibration, a nested running union of LCC masks, an established monotone loss envelope, fixed-marker reconstruction, and area opening.',
'results':f"LCC cleanup increased mean missed annotated area from {pct(a.loc['Raw CRC','risk'])}% to {pct(a.loc['Raw CRC + LCC','risk'])}% for PraNet and from {pct(b.loc['Raw CRC','risk'])}% to {pct(b.loc['Raw CRC + LCC','risk'])}% for Polyp-PVT. Running-union calibration attained {pct(a.loc['Prefix union CRC','risk'])}% and {pct(b.loc['Prefix union CRC','risk'])}% missed area, respectively. Fixed-marker reconstruction attained {pct(a.loc['Anchor CRC','risk'])}% and {pct(b.loc['Anchor CRC','risk'])}%, using {pct(a.loc['Anchor CRC','area'])}% and {pct(b.loc['Anchor CRC','area'])}% of frame area. Loss-envelope calibration retained single-component outputs but occupied {pct(a.loc['LCC envelope CRC','area'])}% and {pct(b.loc['LCC envelope CRC','area'])}% of frames. LCC paths were nonnested in 554/701 PraNet images and 469/701 Polyp-PVT images. Four-connectivity and denser-grid PraNet analyses retained the cleanup effect.",
'conclusions':'Largest-component cleanup can remove polyp pixels that supported a recall guarantee. Calibration must address the final returned mask. Increasing connected filters offered practical alternatives; retaining a single largest component could require nearly full-frame masks. These retrospective image-level results support pipeline validation, without establishing clinical detection benefit.'}
title='Preserving Recall Calibration through Connected-Component Filtering in Polyp Segmentation'
obj={'title':title,'author':'Shivam Gupta','affiliation':'Independent Researcher, India','presentation':'Oral Presentation','topic':'Artificial Intelligence / Others','body':body,'body_word_count':sum(len(v.split()) for v in body.values()),'title_word_count':len(title.split())}
assert obj['body_word_count']<=300;assert obj['title_word_count']<=30
(r/'submission/abstract.json').write_text(json.dumps(obj,indent=2))
labels={'objectives':'Background/Aim','methods':'Methods','results':'Results','conclusions':'Conclusions'}
(r/'submission/abstract.txt').write_text(title+'\n\nShivam Gupta\nIndependent Researcher, India\n\n'+'\n\n'.join(labels[k]+'\n'+v for k,v in body.items())+f"\n\nBody: {obj['body_word_count']} words. Title: {obj['title_word_count']} words.\n")
print(obj['body_word_count'],obj['title_word_count']);print(body['results'])
